sp_widget.css:
@import url('https://cdnjs.cloudflare.com/ajax/libs/font-awesome/4.7.0/css/font-awesome.min.css');

.saas-landing {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: #0c0c0e;
  color: #ffffff;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

a {
  text-decoration: none;
}

/* Banner */
.saas-banner {
  background: linear-gradient(90deg, #ff4b2b 0%, #ff416c 100%);
  color: white;
  text-align: center;
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 500;
}
.saas-badge {
  background: rgba(255, 255, 255, 0.2);
  padding: 2px 8px;
  border-radius: 12px;
  font-size: 11px;
  font-weight: bold;
  margin-right: 8px;
}
.saas-banner a {
  color: white;
  text-decoration: underline;
  font-weight: 600;
  margin-left: 4px;
}

/* Navigation */
.saas-nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 40px;
  background: rgba(12, 12, 14, 0.8);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  position: sticky;
  top: 0;
  z-index: 100;
}
.saas-nav-left, .saas-nav-right {
  display: flex;
  align-items: center;
  gap: 24px;
}
.saas-logo {
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.5px;
}
.saas-logo-dot {
  color: #ff4b2b;
}
.saas-nav-links a {
  color: #a1a1a6;
  font-size: 14px;
  font-weight: 500;
  margin-left: 20px;
  transition: color 0.2s;
}
.saas-nav-links a i {
  font-size: 10px;
  margin-left: 4px;
}
.saas-nav-links a:hover, .saas-icon-link:hover, .saas-link:hover {
  color: #ffffff;
}
.saas-icon-link, .saas-link {
  color: #a1a1a6;
  font-size: 14px;
  font-weight: 500;
  transition: color 0.2s;
}
.saas-btn-primary {
  background: linear-gradient(90deg, #ff4b2b 0%, #ff416c 100%);
  color: white;
  padding: 8px 16px;
  border-radius: 6px;
  font-size: 14px;
  font-weight: 600;
  transition: transform 0.2s, box-shadow 0.2s;
}
.saas-btn-primary:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(255, 75, 43, 0.3);
  color: white;
}

/* Hero Section */
.saas-hero {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 80px 20px 40px;
  overflow: hidden;
}
.saas-grid-bg {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-image: 
    linear-gradient(rgba(255, 255, 255, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.03) 1px, transparent 1px);
  background-size: 60px 60px;
  z-index: 1;
  -webkit-mask-image: radial-gradient(ellipse at center, black 40%, transparent 80%);
}
.saas-hero-content {
  position: relative;
  z-index: 2;
  text-align: center;
  max-width: 800px;
  width: 100%;
}

.saas-pill {
  display: inline-block;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 6px 16px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 1px;
  color: #a1a1a6;
  margin-bottom: 24px;
}
.saas-pill i {
  color: #ff4b2b;
  margin-right: 6px;
}

.saas-title {
  font-size: 64px;
  font-weight: 900;
  margin: 0 0 20px;
  line-height: 1.1;
  letter-spacing: -1px;
}
.saas-gradient-text {
  background: linear-gradient(90deg, #ff4b2b 0%, #ff416c 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.saas-subtitle {
  font-size: 18px;
  color: #a1a1a6;
  line-height: 1.5;
  margin: 0 auto 40px;
  max-width: 600px;
}

.saas-hero-actions {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-bottom: 50px;
}

.saas-btn-gradient {
  background: linear-gradient(90deg, #ff4b2b 0%, #ff416c 100%);
  color: white;
  padding: 12px 28px;
  border-radius: 8px;
  font-size: 16px;
  font-weight: 600;
  box-shadow: 0 0 20px rgba(255, 75, 43, 0.4);
  transition: all 0.3s;
}
.saas-btn-gradient:hover {
  box-shadow: 0 0 30px rgba(255, 75, 43, 0.6);
  transform: translateY(-2px);
  color: white;
}

.saas-btn-outline {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: white;
  padding: 12px 28px;
  border-radius: 8px;
  font-size: 16px;
  font-weight: 600;
  transition: all 0.3s;
}
.saas-btn-outline:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.2);
  color: white;
}

/* AI Search Bar */
.saas-search-container {
  padding: 2px;
  background: linear-gradient(90deg, rgba(255, 75, 43, 0.5) 0%, rgba(255, 65, 108, 0.5) 100%);
  border-radius: 12px;
  margin: 0 auto 30px;
  max-width: 650px;
}
.saas-search-box {
  background: #151518;
  border-radius: 10px;
  display: flex;
  align-items: center;
  padding: 8px 16px;
}
.saas-search-icon {
  color: #ff4b2b;
  font-size: 18px;
  margin-right: 12px;
}
.saas-search-box input {
  flex: 1;
  background: transparent;
  border: none;
  color: white;
  font-size: 16px;
  padding: 10px 0;
  outline: none;
}
.saas-search-box input::placeholder {
  color: #666;
}
.saas-search-submit {
  background: transparent;
  border: 1px solid rgba(255,255,255,0.1);
  color: #a1a1a6;
  border-radius: 50%;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s;
}
.saas-search-submit:hover {
  background: rgba(255, 255, 255, 0.1);
  color: white;
}

/* Tags */
.saas-tags {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-bottom: 40px;
  flex-wrap: wrap;
}
.saas-tag {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #a1a1a6;
  padding: 8px 20px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 500;
  transition: all 0.2s;
}
.saas-tag:hover {
  background: rgba(255, 255, 255, 0.1);
  color: white;
}

.saas-trust {
  color: #666;
  font-size: 14px;
}
.saas-highlight {
  color: #ff4b2b;
  font-weight: 600;
}

/* Standard Home */
.saas-standard-home {
  text-align: center;
  margin: 40px 0 80px;
  position: relative;
  z-index: 2;
}
.saas-btn-standard {
  background: transparent;
  border: 1px solid #333;
  color: #a1a1a6;
  padding: 12px 24px;
  border-radius: 30px;
  font-size: 14px;
  font-weight: 500;
  transition: all 0.2s;
}
.saas-btn-standard i {
  margin-right: 6px;
}
.saas-btn-standard:hover {
  background: rgba(255, 255, 255, 0.05);
  color: white;
  border-color: #555;
}

/* Footer */
.saas-footer {
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  padding: 40px;
  position: relative;
  z-index: 2;
  background: #09090b;
}
.saas-footer-content {
  display: flex;
  justify-content: space-between;
  align-items: center;
  max-width: 1000px;
  margin: 0 auto 30px;
}
.saas-footer-left p {
  color: #666;
  font-size: 12px;
  margin-top: 4px;
}
.saas-footer-links {
  display: flex;
  gap: 24px;
}
.saas-footer-links a {
  color: #ffffff;
  font-size: 14px;
  font-weight: 600;
}
.saas-footer-links a:hover {
  color: #ff4b2b;
}
.saas-footer-socials {
  display: flex;
  gap: 16px;
}
.saas-footer-socials a {
  background: rgba(255, 255, 255, 0.05);
  color: #a1a1a6;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}
.saas-footer-socials a:hover {
  background: rgba(255, 255, 255, 0.1);
  color: white;
}

.saas-footer-bottom {
  display: flex;
  justify-content: space-between;
  max-width: 1000px;
  margin: 0 auto;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  padding-top: 20px;
  color: #666;
  font-size: 12px;
}

sp_widget.script:
(function() {

    // Impact statistics
    data.impactStats = [
