        }
    ];


    // Login information
    data.isLoggedIn = !gs.isGuestUser();

    if (data.isLoggedIn) {
        data.userName = gs.getUserDisplayName();

        // Determine user role
        if (gs.hasRole('wei_supervisor')) {
            data.userRole = 'Supervisor';

        } else if (gs.hasRole('wei_technician')) {
            data.userRole = 'Technician';

        } else if (gs.hasRole('wei_admin')) {
            data.userRole = 'Admin';

        } else {
            data.userRole = 'Staff';
        }

    } else {
        data.userName = '';
        data.userRole = '';
    }

})();
